<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();if($u['role']==='admin')go('../admin/dashboard.php');$id=(int)$u['id'];$pdo=db();$stats=[];$q=$pdo->prepare("SELECT COUNT(*) FROM study_requests WHERE status='accepted' AND (sender_id=? OR receiver_id=?)");$q->execute([$id,$id]);$stats['partners']=$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM study_requests WHERE receiver_id=? AND status='pending'");$q->execute([$id]);$stats['requests']=$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM group_members WHERE user_id=?');$q->execute([$id]);$stats['groups']=$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM study_sessions WHERE status='scheduled' AND session_date>=CURDATE() AND (created_by=? OR partner_id=? OR group_id IN (SELECT group_id FROM group_members WHERE user_id=?))");$q->execute([$id,$id,$id]);$stats['sessions']=$q->fetchColumn();$q=$pdo->prepare('SELECT * FROM student_profiles WHERE user_id=?');$q->execute([$id]);$p=$q->fetch();$pct=completion($p?:[]);$partners=$pdo->prepare("SELECT u.id,u.name,p.course,p.college FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE u.id<>? AND u.status='active'");$partners->execute([$id]);$rec=[];foreach($partners as $person){$m=match_info($id,(int)$person['id']);$person['score']=$m['score'];$person['why']=$m['why'];$rec[]=$person;}usort($rec,fn($a,$b)=>$b['score']<=>$a['score']);$rec=array_slice($rec,0,3);$sessions=$pdo->prepare("SELECT s.*,g.name group_name FROM study_sessions s LEFT JOIN study_groups g ON g.id=s.group_id WHERE s.status='scheduled' AND s.session_date>=CURDATE() AND (s.created_by=? OR s.partner_id=? OR s.group_id IN (SELECT group_id FROM group_members WHERE user_id=?)) ORDER BY s.session_date,s.start_time LIMIT 5");$sessions->execute([$id,$id,$id]);page_start('Dashboard'); ?>
<div class="mb-4"><h2 class="h4 fw-bold">Welcome back, <?= e(explode(' ',$u['name'])[0]) ?> 👋</h2><p class="text-secondary">Ready to learn something new today?</p></div><div class="row g-3 mb-4"><?php foreach(['Study partners'=>'partners','Pending requests'=>'requests','Study groups'=>'groups','Upcoming sessions'=>'sessions'] as $label=>$key): ?><div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-secondary small"><?= e($label) ?></div><div class="stat"><?= (int)$stats[$key] ?></div></div></div></div><?php endforeach ?></div><div class="row g-4"><div class="col-lg-8"><div class="d-flex justify-content-between mb-3"><h2 class="h5 fw-bold">Recommended partners</h2><a href="find-partners.php">See all</a></div><div class="row g-3"><?php foreach($rec as $r): ?><div class="col-md-4"><div class="card h-100"><div class="card-body"><div class="d-flex gap-3 align-items-center"><div class="avatar"><?= e(mb_substr($r['name'],0,1)) ?></div><div><div class="fw-bold"><?= e($r['name']) ?></div><small class="text-secondary"><?= e($r['course']) ?></small></div></div><div class="match mt-3"><?= $r['score'] ?>% match</div><p class="small text-secondary mt-2"><?= e(implode(' · ',array_slice($r['why'],0,2))?:'A new connection to explore') ?></p><a class="btn btn-sm btn-outline-primary" href="partner-details.php?id=<?= (int)$r['id'] ?>">View profile</a></div></div></div><?php endforeach ?></div><div class="card mt-4"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5 fw-bold">Upcoming sessions</h2><a href="sessions.php">View all</a></div><?php foreach($sessions as $s): ?><div class="d-flex justify-content-between border-top py-3"><div><strong><?= e($s['title']) ?></strong><div class="small text-secondary"><?= e($s['subject']??'Study session') ?> · <?= e($s['group_name']??$s['mode']) ?></div></div><div class="small text-end"><?= e($s['session_date']) ?><br><?= e(substr($s['start_time'],0,5)) ?></div></div><?php endforeach ?></div></div></div><div class="col-lg-4"><div class="card mb-3"><div class="card-body"><div class="d-flex justify-content-between"><strong>Profile completion</strong><span class="fw-bold"><?= $pct ?>%</span></div><div class="progress my-3"><div class="progress-bar" style="width:<?= $pct ?>%;background:#635bdb"></div></div><p class="small text-secondary">Add your learning goals, study preferences, and availability so partners can find a better fit.</p><a href="edit-profile.php">Complete your profile →</a></div></div><div class="card"><div class="card-body"><h3 class="h6 fw-bold">Quick links</h3><a class="d-block py-2" href="find-partners.php">Explore study partners</a><a class="d-block py-2" href="groups.php">Browse study groups</a><a class="d-block py-2" href="sessions.php">Schedule a session</a></div></div></div></div><?php page_end(); ?>
